const input = $input.first().json;
const event = input.body ?? input;
for (const key of ['specversion', 'id', 'source', 'type', 'data']) { if (event[key] === undefined || event[key] === null) throw new Error(`missing CloudEvent field: ${key}`); }
if (event.specversion !== '1.0') throw new Error(`unsupported CloudEvents specversion: ${event.specversion}`);
if (event.type !== 'io.ordivon.distribution.admission.v1') throw new Error(`unexpected event type: ${event.type}`);
if (!event.data.decision || typeof event.data.decision.action !== 'string') throw new Error('missing Distribution decision');
if (event.data.decision.externalEffectPerformed !== false) throw new Error('integration edge refuses a decision claiming an external effect already occurred');
return [{ json: event }];

const issue = $input.first().json;
const event = $('Validate Distribution Event').first().json;
if (issue.number !== 72 || !issue.id || !issue.node_id) throw new Error('GitHub readback identity mismatch');
return [{ json: { specversion: '1.0', id: `${event.id}:n8n-readback`, source: 'urn:ordivon:integration:n8n', type: 'io.ordivon.integration.distribution.readback.v1', subject: event.id, time: new Date().toISOString(), datacontenttype: 'application/json', correlationid: event.id, data: { admissionAction: event.data.decision.action, requestedEffect: event.data.intent?.effectName ?? null, provider: 'github', providerCalled: true, externalMethod: 'GET', observedObject: { kind: 'issue', number: issue.number, id: issue.id, nodeId: issue.node_id, state: issue.state }, externalEffectPerformed: false } } }];
